// Generates the typed API client and TanStack Query hooks from the backend's OpenAPI document.
// Run with `npm run generate:api`. Never edit src/api/generated by hand.
export default {
  input: '../backend/openapi.json',
  output: {
    path: 'src/api/generated',
  },
  plugins: ['@hey-api/client-fetch', '@hey-api/typescript', '@hey-api/sdk', '@tanstack/react-query'],
}
